// Generate full slugified list with neighbors
const allGeneratedCities = [];

states.forEach(st => {
  const list = stateCitiesData[st.slug] || [];
  list.forEach(c => {
    const slug = c.name.toLowerCase().trim().replace(/[\s\W-]+/g, '-');
    allGeneratedCities.push({
      state: st.name,
      stateSlug: st.slug,
      stateAbbr: st.abbr,
      name: c.name,
      slug: slug,
      county: c.county,
      population: c.pop,
      zips: c.zips,
      medianHomeAge: c.year,
      hailRisk: c.hail,
      windRisk: c.wind,
      permitDept: c.permit,
      tier: c.tier || 2,
      passesQualityGate: true,
      isIndexable: true
    });
  });
});

// Calculate nearby sibling cities
allGeneratedCities.forEach(city => {
  const sameState = allGeneratedCities.filter(c => c.stateSlug === city.stateSlug && c.slug !== city.slug);
  city.nearbyCities = sameState.slice(0, 8).map(c => ({
    name: c.name,
    slug: c.slug,
    state: c.state,
    stateSlug: c.stateSlug
  }));
});

const outputPath = path.join(__dirname, '../src/_data/cities.json');
fs.writeFileSync(outputPath, JSON.stringify(allGeneratedCities, null, 2), 'utf8');

console.log(`Successfully generated ${allGeneratedCities.length} cities across ALL 50 states + DC!`);
